/** Shared Legends composition. The Expo copy is generated by sync-legend-poster.mjs.
 * Keep layout and graph semantics here; runtime adapters resolve fonts/images. */
export interface LegendPosterDay {
  readonly day: string; readonly attackTrophies: number; readonly defenseTrophies: number;
  readonly trophies: number; readonly closingTrophies?: number | null;
  readonly attacks?: number; readonly defenses?: number; readonly recordedDefenses?: number;
}
export interface LegendPosterFavorite {
  readonly category: "troop" | "spell" | "hero" | "equipment" | "pet" | "siege";
  readonly id: number; readonly name: string; readonly attacks: number;
}
export interface LegendPosterInput {
  readonly player: {readonly name:string; readonly tag:string; readonly trophies?:number;
    readonly townHallLevel?:number; readonly clan?:{readonly name:string};
    readonly globalRank?:number; readonly location?:{readonly name:string;readonly countryCode?:string}};
  readonly season: {readonly seasonStart:string;readonly seasonEnd:string;readonly rankPopulation?:number;
    readonly favorites?:readonly LegendPosterFavorite[];
    readonly stats:{readonly attacks:number;readonly defenses:number;readonly attackTriples:number;readonly defenseTriples:number;
      readonly offenseStars?:{readonly zero:number;readonly one:number;readonly two:number;readonly three:number};
      readonly defenseStars?:{readonly zero:number;readonly one:number;readonly two:number;readonly three:number}}};
  readonly days:readonly LegendPosterDay[];readonly selectedDay:string;readonly today:string;
}
export interface LegendPosterArtwork {
  readonly sword:string;readonly shield:string;readonly trophy:string;readonly league:string;
  readonly star:string;readonly logo:string;readonly prince:string;readonly heart:string;
  readonly hallImage?:string;readonly badge?:string;readonly flag?:string;
  readonly favoriteImages:Readonly<Record<number,string|undefined>>;
}
const xml=(value:unknown)=>String(value).replace(/[&<>"']/gu,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&apos;"})[c]!);
const fmt=(value:number)=>value.toLocaleString("en-US");
const signed=(value:number)=>`${value>=0?"+":""}${fmt(Math.round(value))}`;
const negativeColor="#D90709"; // ClashKing primaryRed; shared by defense and negative net values.
const positiveColor="#14A37F"; // App donationGreen / statColors.win.
// ASCII advances from the bundled Blogger Sans hmtx table (1000 units/em).
// Center the occupied Favorites row, not six mostly-empty equal-width cells.
const bloggerAdvances=[300,247,362,561,513,723,662,242,296,295,515,520,250,419,250,320,520,520,520,520,520,520,520,520,520,520,250,250,645,520,645,482,764,569,562,502,574,494,494,540,600,247,405,527,475,729,620,580,550,580,595,506,503,592,556,803,527,503,504,314,320,314,346,620,217,502,510,418,513,460,349,513,527,265,265,463,248,798,529,494,503,510,357,426,341,529,450,675,451,443,409,427,247,427,475];
const textWidth=(value:string,size:number)=>[...value.normalize("NFD").replace(/\p{M}/gu,"")].reduce((width,char)=>width+(bloggerAdvances[char.charCodeAt(0)-32]??600),0)*size/1000;
export const posterTextWidth=textWidth;
export function legendPosterSvg(input:LegendPosterInput,images:LegendPosterArtwork):string {
  const {hallImage,badge,flag,favoriteImages}=images;
  const {player,season,selectedDay,today}=input,stats=season.stats;
  const days=[...input.days].sort((a,b)=>a.day.localeCompare(b.day));
  // Never draw today's unfinished result as a completed-day zero. The live
  // day is a separate focus card; only closed, observed days enter the graph.
  const closed=days.filter(day=>day.day<today&&(day.attacks!==undefined?day.attacks>0||(day.recordedDefenses??0)>0:day.attackTrophies!==0||day.defenseTrophies!==0));
  const fullOff=closed.filter(day=>day.attacks===8),fullDef=closed.filter(day=>day.defenses===8),fullNet=closed.filter(day=>day.attacks===8&&day.defenses===8);
  const average=(rows:LegendPosterDay[],key:"attackTrophies"|"defenseTrophies"|"trophies")=>rows.length?rows.reduce((sum,row)=>sum+row[key],0)/rows.length:null;
  const number=(day:string)=>Math.round((Date.parse(day)-Date.parse(season.seasonStart.slice(0,10)))/86400000)+1;
  // Season boundaries are UTC dates; local formatting must not shift them back a day.
  const start=new Date(season.seasonStart),end=new Date(season.seasonEnd);
  const dateLabel=(date:Date,year:boolean)=>date.toLocaleDateString("en-US",{month:"short",day:"numeric",...(year?{year:"numeric" as const}:{}),timeZone:"UTC"});
  const seasonRange=`${dateLabel(start,start.getUTCFullYear()!==end.getUTCFullYear())} – ${dateLabel(end,true)}`;
  const rankingX=Math.min(900,Math.max(176+textWidth(player.name.slice(0,36),40),(badge?212:176)+textWidth(player.clan?.name??player.tag,25))+64);
  const text=(x:number,y:number,value:unknown,size=24,color="#dfe4ef",extra="")=>`<text x="${x}" y="${y}" fill="${color}" font-family="Blogger Sans" font-size="${size}" ${extra}>${xml(value)}</text>`;
  const image=(uri:string,x:number,y:number,w:number,h=w,extra="")=>`<image href="${uri}" x="${x}" y="${y}" width="${w}" height="${h}" preserveAspectRatio="xMidYMid meet" ${extra}/>`;
  let svg=`<svg xmlns="http://www.w3.org/2000/svg" width="1600" height="1100" viewBox="0 0 1600 1100"><defs>
    <linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#f6d170" stop-opacity=".17"/><stop offset="1" stop-color="#f6d170" stop-opacity="0"/></linearGradient>
    <radialGradient id="leagueGlow"><stop stop-color="#f5a544" stop-opacity=".32"/><stop offset=".18" stop-color="#f5a544" stop-opacity=".1"/><stop offset=".5" stop-color="#f5a544" stop-opacity=".035"/><stop offset="1" stop-color="#f5a544" stop-opacity="0"/></radialGradient>
    </defs><rect width="1600" height="1100" fill="#000000"/>
    <circle cx="1360" cy="144" r="1450" fill="url(#leagueGlow)"/>
    ${image(images.league,1240,24,240)}
    ${image(images.logo,48,38,76,76)}
    <text x="146" y="76" dominant-baseline="central" fill="#f5f2e8" font-family="Supercell-Magic" font-size="38">LEGEND SEASON<tspan dx="18" dominant-baseline="central" font-family="Blogger Sans" font-size="24" fill="#a1a1aa">(${xml(seasonRange)})</tspan></text>
    ${hallImage?image(hallImage,48,142,106,112):""}
    ${text(176,176,player.name.slice(0,36),40,"#ffffff",'font-weight="700"')}
    ${badge?image(badge,176,190,28):""}
    ${text(badge?212:176,213,player.clan?.name??player.tag,25,"#d4d4d8")}
    ${flag?image(flag,176,228,28,20):""}
    ${text(flag?214:176,246,player.location?.name??player.tag,20,"#a1a1aa")}
    ${player.globalRank?text(rankingX,202,`#${fmt(player.globalRank)}`,56,"#fafafa",'font-weight="700"'):""}
    ${player.globalRank&&season.rankPopulation&&player.globalRank<=season.rankPopulation?text(rankingX,230,`Top ${(player.globalRank/season.rankPopulation*100).toFixed(1)}% tracked`,26,"#a1a1aa"):""}`;
  const cards=[
    {label:"Average offense",value:average(fullOff,"attackTrophies"),color:positiveColor,image:images.sword},
    {label:"Average defense",value:average(fullDef,"defenseTrophies"),color:negativeColor,image:images.shield},
    {label:"Average net",value:average(fullNet,"trophies"),color:"#ffffff",image:images.trophy},
    {label:"Current trophies",value:player.trophies??null,color:"#ffffff",image:images.league},
  ];
  // Center the entire icon + two-line stat group in each cell. The larger
  // icon sits at the text block's vertical midpoint, not on its label line.
  cards.forEach((card,i)=>{const center=80+180+i*360;svg+=image(card.image,center-124,317,48)+text(center-56,321,card.label,23,"#a1a1aa")+text(center-56,384,card.value===null?"—":i===3?fmt(card.value):signed(card.value),56,card.color,'font-weight="700"');});
  const distribution=(x:number,title:string,counts:typeof stats.offenseStars,total:number,triples:number,color:string,icon:string)=>{
    let block=image(icon,x,426,28)+text(x+40,448,title,26,"#f4f4f5",'font-weight="700"')+text(x+710,448,`${total?Math.round(triples/total*1000)/10:0}% triples`,22,color,'text-anchor="end"');
    const keys=["three","two","one","zero"] as const;
    keys.forEach((key,index)=>{const y=472+index*35,value=counts?.[key],ratio=value!==undefined&&total?value/total:0;
      for(let starIndex=0;starIndex<3;starIndex++)block+=image(images.star,x+20+starIndex*23,y-15,21,21,starIndex<3-index?"":'opacity=".13"');
      block+=`<rect x="${x+102}" y="${y-10}" width="456" height="12" rx="6" fill="#0d121c"/>`;
      if(ratio)block+=`<rect x="${x+102}" y="${y-10}" width="${Math.max(4,456*ratio)}" height="12" rx="6" fill="${color}" opacity="${1-index*.16}"/>`;
      block+=text(x+710,y+2,value===undefined?"—":`${fmt(value)} · ${total?Math.round(ratio*100):0}%`,19,"#d4d4d8",'text-anchor="end"');
    });return block;
  };
  svg+=distribution(48,"Offense",stats.offenseStars,stats.attacks,stats.attackTriples,positiveColor,images.sword);
  svg+=distribution(830,"Defense",stats.defenseStars,stats.defenses,stats.defenseTriples,negativeColor,images.shield);
  // Vector artwork avoids a missing emoji glyph in the bundled poster fonts.
  svg+=`<g transform="translate(48 600) scale(1.16)"><path d="M13 1C15 7 21 9 21 15a9 9 0 1 1-18 0c0-4 2-7 5-10-1 5 1 7 2 7 3-3 3-7 3-11Z" fill="#f58a24"/><path d="M12 11c1 4 5 5 5 8a5 5 0 0 1-10 0c0-3 3-5 5-8Z" fill="#ffd36b"/></g>`+text(88,624,"Favorites",24,"#f4f4f5",'font-weight="700"');
  const categories=["troop","spell","hero","equipment","pet","siege"] as const;
  const favoriteWidths=categories.map(category=>{
    const item=season.favorites?.find(value=>value.category===category);
    return Math.max(textWidth(category,17),58+Math.min(183,textWidth(item?.name??"—",20)),item?58+textWidth(`${item.attacks} uses`,17):0);
  });
  const occupiedWidth=favoriteWidths.reduce((sum,width)=>sum+width,0);
  // Distribute the free width between items, not around a tightly packed row.
  // The first item then sits under the Favorites header and both edges agree.
  const favoriteGap=Math.max(0,(1504-occupiedWidth)/(categories.length-1));
  let favoriteX=48;
  categories.forEach((category,i)=>{
    const x=favoriteX,item=season.favorites?.find(value=>value.category===category),uri=item?favoriteImages[item.id]:undefined;
    favoriteX+=favoriteWidths[i]!+favoriteGap;
    svg+=text(x,650,category[0]!.toUpperCase()+category.slice(1),17,"#a1a1aa");
    if(uri)svg+=image(uri,x,659,48);
    const name=item?.name??"—";
    // Shared name/count baselines keep the six tiles aligned. Fit long names
    // within their column instead of reserving an empty second line on all tiles.
    svg+=text(x+58,674,name,20,"#fafafa",`font-weight="700"${textWidth(name,20)>183?' textLength="183" lengthAdjust="spacingAndGlyphs"':""}`);
    if(item)svg+=text(x+58,699,`${item.attacks} uses`,17,"#a1a1aa");
  });
  const snapshots=closed.filter(day=>day.closingTrophies!=null),useClosings=snapshots.length>=2;
  // Closing cups only come from stored snapshots. A net-change curve is named
  // explicitly and is never reverse-filled from the player's current trophies.
  let cumulative=0;
  const points=(useClosings?snapshots:closed).map(day=>({day,n:number(day.day),value:useClosings?day.closingTrophies!:(cumulative+=day.trophies)}));
  if(points.length){
    const left=126,right=1508,top=753,bottom=940,last=Math.max(2,...points.map(p=>p.n));
    const rawMin=Math.min(...points.map(p=>p.value),...(useClosings?[]:[0])),rawMax=Math.max(...points.map(p=>p.value),...(useClosings?[]:[0]));
    const target=Math.max(10,(rawMax-rawMin)/5),power=10**Math.floor(Math.log10(target));
    const stepSize=([1,2,5,10].find(multiplier=>multiplier*power>=target)??10)*power;
    const min=Math.floor(rawMin/stepSize)*stepSize,max=Math.max(min+stepSize,Math.ceil(rawMax/stepSize)*stepSize),ticks=Math.round((max-min)/stepSize);
    const px=(n:number)=>left+(n-1)/(last-1)*(right-left),py=(v:number)=>bottom-(v-min)/(max-min)*(bottom-top);
    for(let i=0;i<=ticks;i++){const y=top+(bottom-top)*i/ticks,value=max-i*stepSize;svg+=`<path d="M${left} ${y}H${right}" stroke="${value===0?"#71717a":"#293246"}" stroke-width="${value===0?1.5:1}"/>`+text(106,y+5,fmt(value),16,"#8392aa",'text-anchor="end"');}
    const path=points.map((p,i)=>`${i?"L":"M"}${px(p.n).toFixed(1)} ${py(p.value).toFixed(1)}`).join(" ");
    if(useClosings)svg+=`<path d="${path} L${px(points[points.length-1]!.n)} ${bottom} L${px(points[0]!.n)} ${bottom} Z" fill="url(#area)"/><path d="${path}" fill="none" stroke="#f1d278" stroke-width="3.5" stroke-linejoin="round"/>`;
    else {
      // Clip the same curve at zero, not at point boundaries: a crossing
      // segment must change color exactly where cumulative net changes sign.
      const zero=py(0),area=`${path} L${px(points[points.length-1]!.n)} ${zero} L${px(points[0]!.n)} ${zero} Z`;
      svg+=`<defs><clipPath id="positive"><rect x="${left-10}" y="${top-10}" width="${right-left+20}" height="${zero-top+10}"/></clipPath><clipPath id="negative"><rect x="${left-10}" y="${zero}" width="${right-left+20}" height="${bottom-zero+10}"/></clipPath></defs>`;
      for(const [clip,color] of [["positive",positiveColor],["negative",negativeColor]])svg+=`<g clip-path="url(#${clip})"><path d="${area}" fill="${color}" opacity=".1"/><path d="${path}" fill="none" stroke="${color}" stroke-width="3.5" stroke-linejoin="round"/></g>`;
    }
    const step=Math.max(1,Math.ceil(points.length/12));
    points.forEach((p,i)=>{const x=px(p.n),y=py(p.value),active=p.day.day===selectedDay;
      const pointColor=useClosings?"#f6dd8e":p.value>=0?positiveColor:negativeColor;
      svg+=`<path d="M${x} ${y+8}V${bottom}" stroke="#27272a" stroke-dasharray="3 7"/><circle cx="${x}" cy="${y}" r="${active?8:5}" fill="#000" stroke="${pointColor}" stroke-width="2.5"/>`;
      if(i%step===0||i===points.length-1||active)svg+=text(x,y-18,useClosings?fmt(p.value):signed(p.value),18,pointColor,'text-anchor="middle" font-weight="700"');
      if(points.length<=25||i%2===0||i===points.length-1){
        svg+=text(x,968,`D${p.n}`,17,"#d7e0ef",'text-anchor="middle"')+text(x,994,signed(p.day.attackTrophies),16,positiveColor,'text-anchor="middle"')+text(x,1017,signed(p.day.defenseTrophies),16,negativeColor,'text-anchor="middle"');
      }
    });
  }else svg+=text(800,831,"No completed tracked days yet",30,"#95a5bd",'text-anchor="middle"');
  // Render the heart as artwork: the bundled text fonts have no emoji glyphs.
  svg+=image(images.heart,1350,1057,22)+text(1552,1075,"Made by Clashking",20,"#a1a1aa",'text-anchor="end"')+"</svg>";
  return svg;
}
